from scipy.stats import ttest_ind

# perfrom t-test between 2 groups

def perform_ttest(group1, group2):
	"""
	Perform a t-test between two groups of data.

	Args:
	group1 (List[float]): The first group of data.
	group2 (List[float]): The second group of data.

	Returns:
	Tuple[float, float]: The t-statistic and p-value of the t-test.
	"""
	t_statistic, p_value = ttest_ind(group1, group2)
	return t_statistic, p_value


